// ---- ⚡ স্পিড ফিক্স: libsignal এর "Closing session: SessionEntry {...}" কনসোল-স্প্যাম বন্ধ (এটাই বট স্লো করছিল) ----
(() => {
  const noise = /Closing session|Opening session|Removing old closed session|Migrating session|Session already (closed|open)|Decrypted message with closed session|Failed to decrypt message with any known session/;
  const isSess = (x) => { try { return x && typeof x === 'object' && (x.constructor?.name === 'SessionEntry' || x._chains || x.currentRatchet); } catch { return false; } };
  for (const k of ['log', 'info', 'warn', 'debug']) {
    const orig = console[k].bind(console);
    console[k] = (...a) => { if ((typeof a[0] === 'string' && noise.test(a[0])) || a.some(isSess)) return; orig(...a); };
  }
})();
process.on('unhandledRejection', (e) => console.error('unhandled:', e?.message || e));
process.on('uncaughtException', (e) => console.error('uncaught:', e?.message || e));
const fs = require('fs');
