// ---- Control Centar: লাইভ অ্যাক্টিভিটি/কানেকশন/এরর লগ (প্যানেলে দেখানোর জন্য) ----
const { EventEmitter } = require('events');
const hub = new EventEmitter(); hub.setMaxListeners(50);
const activityLog = new Map(); // number -> [{cmd,t}] সবচেয়ে নতুনটা শুরুতে, সর্বোচ্চ ৫০টা
const errorLog = new Map();    // number -> [{msg,t}] সর্বোচ্চ ৩০টা
const connLog = [];            // সব নাম্বারের কানেকশন ইভেন্ট, সর্বোচ্চ ২০০টা
const usageCount = new Map();  // number -> { cmd: count }
function logActivity(n, cmd) {
  if (!n) return;
  const l = activityLog.get(n) || []; l.unshift({ cmd, t: Date.now() }); if (l.length > 50) l.length = 50;
  activityLog.set(n, l);
  const u = usageCount.get(n) || {}; u[cmd] = (u[cmd] || 0) + 1; usageCount.set(n, u);
  hub.emit('activity', { n, cmd, t: Date.now() });
}
function logError(n, msg) {
  if (!n) return;
  const l = errorLog.get(n) || []; l.unshift({ msg: String(msg).slice(0, 300), t: Date.now() }); if (l.length > 30) l.length = 30;
  errorLog.set(n, l);
  hub.emit('error', { n, msg: String(msg).slice(0, 300), t: Date.now() });
}
function logConn(n, state) {
  if (!n) return;
  connLog.unshift({ n, state, t: Date.now() }); if (connLog.length > 200) connLog.length = 200;
  hub.emit('conn', { n, state, t: Date.now() });
}
// ---- Control Centar: ব্যান লিস্ট ও মেইনটেনেন্স মোড ----
const BAN_FILE = './data/banned.json';
let bannedSet = new Set();
try { bannedSet = new Set(JSON.parse(fs.readFileSync(BAN_FILE, 'utf8'))); } catch {}
function saveBans() { try { fs.mkdirSync('./data', { recursive: true }); fs.writeFileSync(BAN_FILE, JSON.stringify([...bannedSet])); } catch {} }
function banNumber(n, reason) {
  n = String(n || '').replace(/\D/g, ''); if (!n) return false;
  bannedSet.add(n); saveBans();
  if (subs[n]) unpairExternal(n); // ব্যান করলে সাথে সাথে ডিসকানেক্টও হয়ে যাবে
  hub.emit('ban', { n, state: 'banned', reason: reason || '', t: Date.now() });
  return true;
}
function unbanNumber(n) {
  n = String(n || '').replace(/\D/g, '');
  const had = bannedSet.delete(n); if (had) saveBans();
  if (had) hub.emit('ban', { n, state: 'unbanned', t: Date.now() });
  return had;
}
const isBanned = (n) => bannedSet.has(String(n || '').replace(/\D/g, ''));
const listBanned = () => [...bannedSet];

let MAINTENANCE = { on: false, msg: '🛠 বট এখন মেইনটেনেন্সে আছে। একটু পরে আবার চেষ্টা করো।' };
function setMaintenance(on, msg) { MAINTENANCE = { on: !!on, msg: msg || MAINTENANCE.msg }; hub.emit('maint', { on: MAINTENANCE.on, t: Date.now() }); }

// প্যানেল থেকে সব কানেক্টেড নাম্বারের নিজের চ্যাটে (self message) একটা ঘোষণা পাঠাতে
async function broadcastAll(text) {
  let ok = 0, fail = 0;
  for (const [n, rec] of Object.entries(subs)) {
    if (!rec.online || !rec.sock) { fail++; continue; }
    try { await rec.sock.sendMessage(rec.sock.user.id, { text }); ok++; } catch { fail++; }
    await new Promise((r) => setTimeout(r, 300)); // স্প্যাম/রেট-লিমিট এড়াতে একটু গ্যাপ
  }
  return { ok, fail };
}
function restartAllSubs() {
  let n = 0;
  for (const num of Object.keys(subs)) { if (restartSub(num)) n++; }
  return n;
}
