const PROG_END = [['িস', 3], ['েন', 5], ['ি', 1], ['ো', 2], ['ে', 4], ['', 2]]; // সাধারণ বাংলা শেষাংশ → পুরুষ (১=আমি, ২=তুমি, ৩=তুই, ৪=সে, ৫=আপনি/তিনি)
