  mymensingh: { name: 'ময়মনসিংহী', prog: { 1: 'তাছি', 2: 'তাছো', 3: 'তাছস', 4: 'তাছে', 5: 'তাছেন' }, words: [...EAST_WORDS, ['কী', 'কি']] },
  comilla: { name: 'কুমিল্লা-ব্রাহ্মণবাড়িয়া অঞ্চলের', prog: { 1: 'তাছি', 2: 'তাছো', 3: 'তাছস', 4: 'তাছে', 5: 'তাছেন' }, words: [...EAST_WORDS, ['বাড়ি', 'বাইত'], ['কেমন', 'ক্যামনে']] },
  noakhali: { name: 'নোয়াখালীর', prog: { 1: 'তাছি', 2: 'তাছো', 3: 'তাছস', 4: 'তাছে', 5: 'তাছেন' }, words: [...EAST_WORDS, ['কেন', 'ক্যা'], ['কোথায়', 'কনে'], ['এখন', 'অন']] },
  chittagong: { name: 'চাটগাঁইয়া (চট্টগ্রামের)', prog: { 1: 'িত্তাছি', 2: 'িত্তাছো', 3: 'িত্তাছস', 4: 'িত্তাছে', 5: 'িত্তাছেন' },
    words: [['আমি', 'আঁই'], ['আমার', 'আঁর'], ['আমাকে', 'আঁরে'], ['আমরা', 'আঁরা'], ['তুমি', 'তুঁই'], ['তোমার', 'তোঁয়ার'], ['তোমাকে', 'তোঁয়ারে'], ['তোমরা', 'তোঁয়ারা'],
      ['কেন', 'কিলাই'], ['কোথায়', 'কডে'], ['ভালো', 'ভালা'], ['ভাল', 'ভালা'], ['বাড়ি', 'বাইত'], ['ছেলে', 'পুয়া'], ['মেয়ে', 'ঝি'], ['হ্যাঁ', 'হ'], ['না', 'নায়'], ['কিছু', 'কিচ্চু'], ['কথা', 'কতা'], ['খাবার', 'খাওন']] },
