let nsfwModel = null, nsfwFailAt = 0, tfLib = null, nsfwLastErr = '';
async function loadNsfw() {
  if (nsfwModel) return nsfwModel;
  if (Date.now() - nsfwFailAt < 5 * 60 * 1000) return null; // ফেল করলে ৫ মিনিট আবার চেষ্টা করবে না
  try {
    tfLib = require('@tensorflow/tfjs');
    const nsfwjs = require('nsfwjs');
    await tfLib.setBackend('cpu'); await tfLib.ready();
    nsfwModel = await nsfwjs.load();
    console.log('✅ NSFW মডেল লোড হয়েছে');
  } catch (e) { console.error('nsfw load:', e.message); nsfwLastErr = e.message; nsfwFailAt = Date.now(); nsfwModel = null; }
  return nsfwModel;
}
const NSFW_PORN = 0.55, NSFW_SEXY = 0.9; // Porn+Hentai এর যোগফল এর বেশি হলে, বা Sexy এর বেশি হলে খারাপ ধরা হবে (বদলাতে পারো)
let nsfwBusy = false;
// ⚡ একসাথে শুধু ১টা ছবি চেক হবে; ব্যস্ত থাকলে বাকিগুলো স্কিপ (null) — CPU ১০০% আটকে বট স্লো করত
async function nsfwScoreImage(buf) {
  if (nsfwBusy) return null;
  nsfwBusy = true;
  try { return await nsfwScoreImageRaw(buf); } finally { nsfwBusy = false; }
}
async function nsfwScoreImageRaw(buf) {
  const model = await loadNsfw(); if (!model) return null;
  let sharp; try { sharp = require('sharp'); } catch (e) { nsfwLastErr = 'sharp ইনস্টল নেই: ' + e.message; console.error('nsfw:', nsfwLastErr); return null; }
  const { data } = await sharp(buf).removeAlpha().resize(224, 224, { fit: 'fill' }).raw().toBuffer({ resolveWithObject: true });
  const t = tfLib.tensor3d(new Uint8Array(data), [224, 224, 3], 'int32');
  try {
    const preds = await model.classify(t);
    const p = Object.fromEntries(preds.map((x) => [x.className, x.probability]));
    return ((p.Porn || 0) + (p.Hentai || 0)) >= NSFW_PORN || (p.Sexy || 0) >= NSFW_SEXY;
  } finally { t.dispose(); }
}
function ffmpegFrame(file, sec, out) {
  return new Promise((res) => execFile('ffmpeg', ['-y', '-loglevel', 'error', '-ss', String(sec), '-i', file, '-frames:v', '1', '-vf', 'scale=320:-1', out], { timeout: 20000 }, (err) => res(!err && fs.existsSync(out))));
}
// মেসেজের ছবি/ভিডিও খারাপ কিনা: true = খারাপ, false = ঠিক আছে, null = চেক করা যায়নি (তখন ছাড় দেওয়া হয়)
async function checkNsfwMsg(m, msg) {
  try {
    if (msg.imageMessage) {
      const buf = await downloadMediaMessage(m, 'buffer', {}, { logger: pino({ level: 'silent' }) });
      return await nsfwScoreImage(buf);
    }
    const vm = msg.videoMessage || msg.ptvMessage;
    if (!vm) return null;
    const thumb = vm.jpegThumbnail ? Buffer.from(vm.jpegThumbnail) : null;
    let results = [];
    if (Number(vm.fileLength || 0) < 8 * 1024 * 1024) {
      const tmp = path.join(os.tmpdir(), `nsfw_${Date.now()}_${Math.random().toString(36).slice(2)}`);
      try {
        const vbuf = await downloadMediaMessage(m, 'buffer', {}, { logger: pino({ level: 'silent' }) });
        fs.writeFileSync(tmp + '.mp4', vbuf);
        const dur = Number(vm.seconds || 4);
        for (const [i, sec] of [Math.max(0.5, dur * 0.4)].entries()) {
          const out = `${tmp}_${i}.jpg`;
          if (await ffmpegFrame(tmp + '.mp4', sec.toFixed(2), out)) { results.push(await nsfwScoreImage(fs.readFileSync(out))); fs.unlink(out, () => {}); }
        }
      } catch (e) { console.error('nsfw video:', e.message); }
      finally { fs.unlink(tmp + '.mp4', () => {}); }
    }
    if (!results.length && thumb) results.push(await nsfwScoreImage(thumb)); // ffmpeg না থাকলে ছোট থাম্বনেইল দিয়ে চেক
    if (!results.length) return null;
    return results.some((r) => r === true);
  } catch (e) { console.error('nsfw check:', e.message); return null; }
}

