// ================= 🆕 নতুন ফিচারের হেল্পার (antinsfw • antilong • antiemoji • antitag • slowmode • lockmedia • safelist • strike • newbie • poll • event • streak) =================
function parseDur(s, defUnit = 'm') { // 30s • 10m • 2h • 1d → মিলিসেকেন্ড (ইউনিট না দিলে defUnit)
  const mm = String(s || '').toLowerCase().trim().match(/^(\d+)\s*(s|sec|secs|m|min|mins|h|hr|hrs|d|day|days)?$/);
  if (!mm) return 0;
  const u = (mm[2] || defUnit)[0];
  return +mm[1] * (u === 's' ? 1e3 : u === 'm' ? 6e4 : u === 'h' ? 36e5 : 864e5);
}
function fmtDur(ms) {
  if (ms >= 864e5 && ms % 864e5 === 0) return `${ms / 864e5} দিন`;
  if (ms >= 36e5 && ms % 36e5 === 0) return `${ms / 36e5} ঘণ্টা`;
  if (ms >= 6e4 && ms % 6e4 === 0) return `${ms / 6e4} মিনিট`;
  return `${Math.max(1, Math.round(ms / 1e3))} সেকেন্ড`;
}
function dhakaYMD(ts = Date.now()) { return new Date(ts + 6 * 36e5).toISOString().slice(0, 10); } // ঢাকার তারিখ YYYY-MM-DD (UTC+6)
const countEmoji = (t) => (String(t || '').match(/\p{Extended_Pictographic}/gu) || []).length;
const noticeAt = {}, slowLog = {}, offLog = {}; // নোটিস থ্রটল / স্লো-মোড / নিয়ম-ভাঙার হিসাব (মেমরিতে)
setInterval(() => {
  const now = Date.now();
  for (const k of Object.keys(noticeAt)) if (now - noticeAt[k] > 36e5) delete noticeAt[k];
  for (const k of Object.keys(slowLog)) if (now - slowLog[k] > 864e5) delete slowLog[k];
  for (const k of Object.keys(offLog)) { const a = offLog[k]; if (!a.length || now - a[a.length - 1] > 6e5) delete offLog[k]; }
}, 10 * 60 * 1000);
function renderPoll(p, final = false) {
  const vals = Object.values(p.votes || {}), total = vals.length;
  const cnt = p.opts.map((_, i) => vals.filter((v) => v === i).length);
  const max = Math.max(0, ...cnt);
  const rows = p.opts.map((o, i) => {
    const pct = total ? Math.round((cnt[i] / total) * 100) : 0, fill = Math.round(pct / 10);
    return `┃ ${i + 1}\uFE0F\u20E3 *${o}*\n┃    ${'▰'.repeat(fill)}${'▱'.repeat(10 - fill)} ${cnt[i]} ভোট (${pct}%)${final && total && cnt[i] === max ? ' 🏆' : ''}`;
  });
  return `╭━━〔 📊 ${final ? '𝗣𝗢𝗟𝗟 𝗥𝗘𝗦𝗨𝗟𝗧' : '𝗣𝗢𝗟𝗟'} 〕━━╮\n┃ ❓ *${p.q}*\n┃ ━━━━━━━━━━━━━━\n${rows.join('\n┃\n')}\n┃ ━━━━━━━━━━━━━━\n┃ 👥 মোট ভোট: *${total}*\n┃ ${final ? '🔒 ভোট শেষ — ধন্যবাদ সবাইকে!' : `👉 ভোট দিতে: *${PREFIX}vote <নম্বর>*`}\n╰━ _${BOT_NAME}_ ━╯`;
}

