// ===== ডিজিটাল ডিজাইনের হেডার (স্টাইল ৩-৬ এর জন্য আলাদা) =====
const dHead = (i = {}, k = 3) => {
  const row = (ic, n, v) => ({ 3: `║ ${ic} ${n === 'OWNER' ? n : n.padEnd(9)}▸ ${v}`, 4: `▌${ic} ${n} :: ${v}`, 5: `│ ${ic} ${n} ⟫ ${v}`, 6: `⟦${ic}⟧ ${n} ⇢ ${v}` }[k]);
  const rows = [
    ['🤴', 'OWNER', i.owner || OWNER_NAME], ['📞', 'OWNER NO', i.ownerNo ? '+' + i.ownerNo : '-'], ['🧑‍💻', 'DEV', DEV_NAME], ['⏱️', 'UPTIME', i.run || '-'], ['🛡️', 'MODE', i.mode || 'PUBLIC'],
    ['🔑', 'PREFIX', PREFIX], ['📊', 'RAM', `${i.ram || '-'} GB`], ['🕰️', 'TIME', i.time || '-'], ['🧑‍🤝‍🧑', 'USER', i.user || '-'], ['🔗', 'PAIR', TG_LINK],
  ].map(([ic, n, v]) => row(ic, n, v)).join('\n');
  const bar = '▰▰▰▰▰▰▰▰▰▰';
  if (k === 3) return `╔═══◤ ⚡ ${BOT_NAME} ⚡ ◢═══╗\n║ 🟢 SYSTEM ONLINE  ${bar}\n╠═══════════════════════\n${rows}\n╚═══════════════════════╝\n`;
  if (k === 4) return `▛▀▀▀▀▀ 💾 *${BOT_NAME}* ▀▀▀▀▀▜\n▌ ◉ STATUS: ONLINE  ${bar}\n▌━━━━━━━━━━━━━━━━━━━━━\n${rows}\n▙▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▄▟\n`;
  if (k === 5) return `┏━━━━━━━ 🖥 *${BOT_NAME}* 🖥 ━━━━━━━┓\n│ [ SYS.BOOT ] ✔ ${bar} 100%\n├───────────────────────\n${rows}\n┗━━━━━━━━━━━━━━━━━━━━━━━┛\n`;
  return `⌈ ◈◈◈ ${BOT_NAME} ◈◈◈ ⌋\n⟦●⟧ NODE STATUS ⇢ ACTIVE ${bar}\n━━━━━━━━━━━━━━━━━━━━━━\n${rows}\n⌊━━━━━━━━━━━━━━━━━━━━⌉\n`;
};
const royalHead = (i = {}) => {
  const r = (ic, n, v) => (n === 'OWNER' ? `║ ${ic} ${n} ➤ ${v}` : `║ ${ic} ${n.padEnd(9)}➤ ${v}`);
  return `╔═══◤ ⚡ ${BOT_NAME} ⚡ ◥═══╗
║ 🟢 SYSTEM ONLINE  ▰▰▰▰▰▰▰▰▰▰ 100%
╠═══════════════════════
${[
    r('👑', 'OWNER', i.owner || OWNER_NAME), r('📞', 'OWNER NO', i.ownerNo ? '+' + i.ownerNo : '-'),
    r('🧑‍💻', 'DEV', DEV_NAME), r('⏱️', 'UPTIME', i.run || '-'), r('🛡️', 'MODE', i.mode || 'PUBLIC'),
    r('🔑', 'PREFIX', PREFIX), r('📊', 'RAM', `${i.ram || '-'} GB`), r('🕰️', 'TIME', i.time || '-'),
    r('👥', 'USER', i.user || '-'), r('🔗', 'PAIR', TG_LINK),
  ].join('\n')}
╚═══════════════════════╝
`;
};
const MENU_STYLES = {
  // ১-২: আগের ক্লাসিক ডিজাইন। ৩-৬: নতুন ডিজিটাল ডিজাইন। সবগুলোতে শুধু কমান্ডের নাম — বিস্তারিত দেখতে .list
  1: (P, cats, HDR, i = {}) => HDR + (i._top || '') +
    cats.map(([t, l]) => `\n╭─❮ ${t} ❯\n` + l.map(([c]) => `│ ${P}${c}`).join('\n') + '\n╰─────────────').join('\n'),
  2: (P, cats, HDR, i = {}) => HDR + (i._top || '') +
    cats.map(([t, l]) => `\n┌─[ ${t} ]\n` + l.map(([c]) => `┃ ${P}${c}`).join('\n') + '\n└─────────────').join('\n'),
  // ৩: টার্মিনাল/সাইবার ফ্রেম
  3: (P, cats, _H, i) => dHead(i, 3) + (i._top || '') +
    cats.map(([t, l], n) => `\n╔══[ ${String(n + 1).padStart(2, '0')} ]═ ${t} ═╗\n` + l.map(([c]) => `║ ▸ ${P}${c}`).join('\n') + '\n╚════════════════════╝').join('\n'),
  // ৪: ব্লক/হ্যাকার স্টাইল
  4: (P, cats, _H, i) => dHead(i, 4) + (i._top || '') +
    cats.map(([t, l]) => `\n▛▀▀ ${t} ▀▀▜\n` + l.map(([c]) => `▌ ◈ ${P}${c}`).join('\n') + '\n▙▄▄▄▄▄▄▄▄▄▄▄▄▄▟').join('\n'),
  // ৫: কোড/কনসোল স্টাইল
  5: (P, cats, _H, i) => dHead(i, 5) + (i._top || '') +
    cats.map(([t, l]) => `\n┏━[ ${t} ]\n` + l.map(([c], j) => `┃ ${String(j + 1).padStart(2, '0')} ➜ ${P}${c}`).join('\n') + '\n┗━━━━━━━━━━━━━━━━━━━━━').join('\n'),
  // ৬: নিয়ন নোড স্টাইল
  6: (P, cats, _H, i) => dHead(i, 6) + (i._top || '') +
    cats.map(([t, l]) => `\n⌈ ${t} ⌋\n` + l.map(([c]) => ` ⟫ ◇ ${P}${c}`).join('\n') + '\n ⌊━━━━━━━━━━━━━━━━━━⌉').join('\n'),
  // ৭: ফিউচারিস্টিক ডিজিটাল (নাম্বার-ওয়ান লুক)
  7: (P, cats, _H, i) => royalHead(i) + (i._top || '') +
    cats.map(([t, l], n) => `\n┏━━[ ${String(n + 1).padStart(2, '0')} ]━ ${t} ━◈\n` + l.map(([c]) => `┃ ▸ ${P}${c}`).join('\n') + '\n┗━━━━━━━━━━━━━━━━━◈').join('\n') +
    `\n\n╔═◤ ⚡ POWERED BY ${BOT_NAME} ⚡ ◥═╗\n╚═ 🌐 ${TG_LINK} ═╝`,
};
const STYLE_COUNT = Object.keys(MENU_STYLES).length;

// ===== 😈 .antilink badword — ডিফল্ট ক্যাপশন (প্রতিবার পরেরটা যায়). নিজের লাইন যোগ করতে: .antilink badword add <লেখা> ({user} = মেনশন) =====
