// ---------- helpers ----------
function unwrap(message) {
  let m = message;
  for (let i = 0; i < 5; i++) {
    const inner = m?.ephemeralMessage?.message || m?.viewOnceMessage?.message ||
      m?.viewOnceMessageV2?.message || m?.viewOnceMessageV2Extension?.message ||
      m?.documentWithCaptionMessage?.message || m?.editedMessage?.message;
    if (!inner) break;
    m = inner;
  }
  return m;
}
// ভিউ-ওয়ান্স (1seen) মেসেজ কিনা — wrapper বা inner মেসেজের viewOnce ফ্ল্যাগ দুটোই দেখা হয়
function isViewOnce(message) {
  let m = message;
  for (let i = 0; i < 6 && m; i++) {
    if (m.viewOnceMessage || m.viewOnceMessageV2 || m.viewOnceMessageV2Extension) return true;
    m = m.ephemeralMessage?.message || m.documentWithCaptionMessage?.message || m.editedMessage?.message;
  }
  const u = unwrap(message);
  return !!(u?.imageMessage?.viewOnce || u?.videoMessage?.viewOnce || u?.audioMessage?.viewOnce);
}
const hasAny = (msg, keys) => keys.some((k) => msg?.[k]);
// WhatsApp আপডেটে Story-র র‍্যাপার/নেস্টিং বদলালেও ধরার জন্য: মেসেজের ভেতরে যেকোনো গভীরতায় groupStatus* ফিল্ড আছে কিনা
const hasGroupStatusDeep = (o, d = 0) => {
  if (!o || typeof o !== 'object' || d > 6) return false;
  for (const k of Object.keys(o)) {
    if (/^groupStatus(Message|MessageV\d+)$/i.test(k) && o[k]) return true;
    if (o[k] && typeof o[k] === 'object' && !Buffer.isBuffer(o[k]) && !(o[k] instanceof Uint8Array) && hasGroupStatusDeep(o[k], d + 1)) return true;
  }
  return false;
};
const hasLink = (t) => /(https?:\/\/|www\.|\b[a-z0-9-]+\.(com|net|org|me|io|xyz|info|bd|link|live|tv|co)\b)/i.test(t);
const isBadWord = (t, extra = []) => BAD_WORDS.concat(extra).some((w) => t.toLowerCase().includes(String(w).toLowerCase()));

function dhakaNow() {
  const p = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Dhaka', hour: '2-digit', minute: '2-digit', hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
  }).formatToParts(new Date());
  const g = (t) => p.find((x) => x.type === t).value;
  return { date: `${g('day')}-${g('month')}-${g('year')}`, wd: g('weekday'), min: (+g('hour') % 24) * 60 + +g('minute') };
}
let timingsCache = { date: '', t: null };
async function getTimings(date) {
  if (timingsCache.date === date) return timingsCache.t;
  const r = await fetch(`https://api.aladhan.com/v1/timingsByCity/${date}?city=${CITY}&country=${COUNTRY}&method=1&school=1`);
  const j = await r.json();
  timingsCache = { date, t: j.data.timings };
  return timingsCache.t;
}
const toMin = (s) => { const [h, m] = s.split(':'); return +h * 60 + +m; };

async function reactSticker(kind) {
  if (!Sticker) return null;
  const r = await fetch(`https://nekos.best/api/v2/${kind}`);
  const url = (await r.json()).results[0].url;
  const buf = Buffer.from(await (await fetch(url)).arrayBuffer());
  return new Sticker(buf, { pack: BOT_NAME, author: DEV_NAME, type: StickerTypes.FULL, quality: 50 }).toMessage();
}

const botState = (n) => (settings['__bot_' + n] ??= { mode: 'public', menustyle: 7 });
const fmtTime = (s) => `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m ${Math.floor(s % 60)}s`;
const hash = (s) => [...s].reduce((a, c) => (a * 31 + c.charCodeAt(0)) >>> 0, 7);
async function getText(url) { const r = await fetch(url); return (await r.text()).trim(); }
async function getJson(url) { return (await fetch(url)).json(); }

// ================== নতুন ফিচার: লগ চ্যানেল / আয়াত / হাদিস / AI ইমেজ ==================
const LOG_ICON = { add: '➕', remove: '🚪', leave: '👋', promote: '⬆️', demote: '⬇️' };
const fmtDhaka = (t) => new Date(t).toLocaleString('en-GB', { timeZone: 'Asia/Dhaka', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: true });
// একটা লগ এন্ট্রি → এক লাইনের বাংলা লেখা (কে কাকে কী করল)
const logLine = (e) => {
  const by = e.by ? mention(e.by) : null;
  const to = (e.to || []).map(mention).join(', ');
  if (e.a === 'remove') return `${LOG_ICON.remove} ${by ? `${by} কিক করল ➜ ${to}` : `${to} কে রিমুভ করা হলো`}`;
  if (e.a === 'promote') return `${LOG_ICON.promote} ${by ? `${by} এডমিন বানাল ➜ ${to}` : `${to} এডমিন হলো`}`;
  if (e.a === 'demote') return `${LOG_ICON.demote} ${by ? `${by} এডমিন থেকে নামাল ➜ ${to}` : `${to} এডমিন থেকে নামল`}`;
  if (e.a === 'add') return `${LOG_ICON.add} ${by ? `${by} অ্যাড করল ➜ ${to}` : `${to} জয়েন করল`}`;
  return `${LOG_ICON.leave} ${to} গ্রুপ ছেড়ে গেল`;
};

