// আরবি + বাংলা অনুবাদসহ আয়াত আনে (alquran.cloud); ref = 1..6236 অথবা "সূরা:আয়াত" (যেমন 2:255)
async function fetchAyah(ref) {
  const r = await fetch(`https://api.alquran.cloud/v1/ayah/${ref}/editions/quran-uthmani,bn.bengali`, { signal: AbortSignal.timeout(10000) });
  if (!r.ok) return null;
  const j = await r.json();
  const [ar, bn] = j.data || [];
  if (!ar?.text) return null;
  return `📖 *আল-কুরআন*\n\n${ar.text}\n\n🌸 *অনুবাদ:* ${bn?.text || '—'}\n\n📌 সূরা ${ar.surah?.englishName || ''} (${ar.surah?.name || ''}) • আয়াত ${ar.numberInSurah}`;
}
