const bnDur = (ms) => { // সময়ের ব্যবধান বাংলায়
  const m = Math.floor(ms / 60000);
  if (m < 1) return 'এক মিনিটেরও কম';
  if (m < 60) return `${bnNum(m)} মিনিট`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${bnNum(h)} ঘণ্টা${m % 60 ? ` ${bnNum(m % 60)} মিনিট` : ''}`;
  const d = Math.floor(h / 24);
  return `${bnNum(d)} দিন${h % 24 ? ` ${bnNum(h % 24)} ঘণ্টা` : ''}`;
};
