const dhakaDayKey = (t = Date.now()) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Dhaka' }).format(new Date(t)); // YYYY-MM-DD
const bumpWeekly = (g, k) => {
  const w = (weeklyData[g] ??= {}), d = dhakaDayKey();
  if (!w[d]) { // নতুন দিন শুরু — ১৪ দিনের পুরনো ডেটা মুছে ফেলা
    w[d] = { t: 0, u: {} };
    const keep = new Set(Array.from({ length: 14 }, (_, i) => dhakaDayKey(Date.now() - i * 864e5)));
    for (const key of Object.keys(w)) if (!keep.has(key)) delete w[key];
  }
  w[d].t++; w[d].u[k] = (w[d].u[k] || 0) + 1; weeklyDirty = true;
};
const WD_BN = ['রবিবার', 'সোমবার', 'মঙ্গলবার', 'বুধবার', 'বৃহস্পতিবার', 'শুক্রবার', 'শনিবার'];
const weeklyReport = (g, subject) => {
  const w = weeklyData[g] || {}, users = {}, days = [];
  let total = 0;
  for (let i = 0; i < 7; i++) {
    const key = dhakaDayKey(Date.now() - i * 864e5), e = w[key];
    if (!e) continue;
    total += e.t; days.push([key, e.t]);
    for (const [k, n] of Object.entries(e.u)) users[k] = (users[k] || 0) + n;
  }
  const top = Object.entries(users).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const best = days.sort((a, b) => b[1] - a[1])[0];
  const medals = ['🥇', '🥈', '🥉', '4️⃣', '5️⃣'];
  const jidOf = (k) => stats[g]?.[k]?.jid || `${k}@s.whatsapp.net`;
  const head = `╭━━〔 📊 𝗪𝗘𝗘𝗞𝗟𝗬 𝗥𝗘𝗣𝗢𝗥𝗧 〕━━╮\n┃ 📛 ${subject || 'গ্রুপ'}\n┃ 🗓 গত ৭ দিনের হিসাব\n┃ ━━━━━━━━━━━━━━━━━━\n`;
  if (!total) return { text: head + '┃ 📭 এখনো কোনো মেসেজ রেকর্ড হয়নি\n┃\n╰━ _' + BOT_NAME + '_ ━╯', mentions: [] };
  const bestDay = WD_BN[new Date(`${best[0]}T12:00:00+06:00`).getUTCDay()];
  return {
    text: head + `┃ 💬 মোট মেসেজ: *${bnNum(total)}*\n┃ 🔥 সবচেয়ে অ্যাক্টিভ দিন: *${bestDay}* (${bnNum(best[1])} মেসেজ)\n┃ ━━━━━━━━━━━━━━━━━━\n┃ 🏆 *টপ চ্যাটার*\n` +
      top.map(([k, n], i) => `┃ ${medals[i]} ${mention(jidOf(k))} — ${bnNum(n)}`).join('\n') + `\n┃\n╰━ _${BOT_NAME}_ ━╯`,
    mentions: top.map(([k]) => jidOf(k)),
  };
};

