const makeCaptcha = () => {
  if (Math.random() < 0.5) {
    const a = 2 + Math.floor(Math.random() * 8), b = 2 + Math.floor(Math.random() * 8);
    const mul = Math.random() < 0.4;
    return { q: `${a} ${mul ? '×' : '+'} ${b} = ?  (শুধু সংখ্যাটা লেখো)`, answer: String(mul ? a * b : a + b), kind: 'math' };
  }
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code = ''; for (let i = 0; i < 4; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return { q: `এই কোডটা হুবহু লেখো: *${code}*`, answer: code, kind: 'code' };
};
