// ---- XP / Level (মেসেজ সংখ্যা ×৫ + গেম বোনাস) — ডেটা আসে ,top এর stats থেকেই ----
const xpOf = (e) => (e?.n || 0) * 5 + (e?.bonus || 0);
const levelOf = (xp) => Math.floor(Math.sqrt(Math.max(0, xp) / 50));
const addBonus = (g, jid, amt) => {
  const k = String(jid).split('@')[0].split(':')[0];
  const e = ((stats[g] ??= {})[k] ??= { n: 0, jid });
  e.bonus = (e.bonus || 0) + amt; statsDirty = true;
};
const rankRows = (g) => Object.entries(stats[g] || {}).map(([k, e]) => [k, e, xpOf(e)]).sort((a, b) => b[2] - a[2]);
const parseDM = (t) => {
  const mm = /^(\d{1,2})[\/\-.](\d{1,2})$/.exec(normAns(t));
  if (!mm) return null;
  const d = +mm[1], mo = +mm[2];
  const dim = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return mo < 1 || mo > 12 || d < 1 || d > dim[mo - 1] ? null : { d, m: mo };
};
const daysUntilBday = (d, m) => {
  const [td, tm, ty] = dhakaNow().date.split('-').map(Number);
  const today = Date.UTC(ty, tm - 1, td);
  let t = Date.UTC(ty, m - 1, d); if (t < today) t = Date.UTC(ty + 1, m - 1, d);
  return Math.round((t - today) / 864e5);
};
