const XO_LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
const xoWinner = (b) => { for (const [x, y, z] of XO_LINES) if (b[x] && b[x] === b[y] && b[x] === b[z]) return b[x]; return null; };
const xoRender = (b) => {
  const nums = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣', '6️⃣', '7️⃣', '8️⃣', '9️⃣'];
  return [0, 1, 2].map((r) => [0, 1, 2].map((c) => { const v = b[r * 3 + c]; return v === 'X' ? '❌' : v === 'O' ? '⭕' : nums[r * 3 + c]; }).join('')).join('\n');
};
