    // ফোনের Linked Devices থেকে সত্যিই সরাতে logout শেষ হতে দেওয়া হয় (সর্বোচ্চ ৬ সেকেন্ড)
    try { if (s && rec.paired) await Promise.race([s.logout(), new Promise((r) => setTimeout(r, 6000))]); } catch {}
