  const isCurrent = () => isMain || !!(subs[opts.sub] && !subs[opts.sub].cancelled && subs[opts.sub].gen === gen);
  const { state, saveCreds } = await useMultiFileAuthState(isMain ? './session' : `${SUB_DIR}/${opts.sub}`);
  const { version } = await fetchLatestBaileysVersion();
  if (!isCurrent()) { // স্টার্ট হতে হতে বাতিল/বদলে গেছে
    if (!isMain && !subs[opts.sub]) { try { fs.rmSync(`${SUB_DIR}/${opts.sub}`, { recursive: true, force: true }); } catch {} }
    return;
  }
