  // কারণ: মেম্বারের ফোন মেসেজ ডিক্রিপ্ট করতে না পারলে WhatsApp বটের কাছে "retry" চায়। getMessage না থাকলে বট
  // আবার পাঠাতে পারে না, ফলে মেসেজ শুধু বট-কানেক্টেড ফোনে দেখা যায়, বাকিরা কিছুই দেখে না।
  const sentStore = new Map(); // id -> proto message
  const rememberSent = (r) => {
    try {
      if (r?.key?.id && r.message) { sentStore.set(r.key.id, r.message); if (sentStore.size > 3000) sentStore.delete(sentStore.keys().next().value); }
    } catch {}
  };
  const retryCounters = new Map();
  const msgRetryCounterCache = {
    get: (k) => retryCounters.get(k),
    set: (k, v) => { retryCounters.set(k, v); if (retryCounters.size > 5000) retryCounters.delete(retryCounters.keys().next().value); },
    del: (k) => retryCounters.delete(k),
    flushAll: () => retryCounters.clear(),
  };
