    if (MENU_LAYOUT === 'joined' || MENU_LAYOUT === 'card') { try { return await sendMenuJoined(jid, cap); } catch (e) { console.error('menu joined:', e.message); _menuVid = null; _menuImg = null; } } // ফেল করলে নিচের আলাদা-ভিডিও লেআউটে ফিরবে
