    try {
      const mk = Object.keys(inside).find((k) => /imageMessage|videoMessage/.test(k));
      const mm = mk ? inside[mk] : {};
      console.log('[gstatus-debug]', JSON.stringify({ field: GS_FIELD, kind, inner: Object.keys(inside), url: !!mm.url, directPath: !!mm.directPath, mediaKey: !!mm.mediaKey, fileLength: String(mm.fileLength || ''), mime: mm.mimetype, thumb: !!mm.jpegThumbnail, baileys: (() => { try { return require('@whiskeysockets/baileys/package.json').version; } catch { return '?'; } })() }));
    } catch {}
